  async function saveSettings() {
    setLoading(true);
    try {
      await new Promise((resolve) => window.setTimeout(resolve, 1200));
    } finally {
      setLoading(false);
    }
  }

  return (
    <Button variant="primary" loading={loading} onClick={saveSettings}>
      保存设置
    </Button>
  );
